</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to rewrite:
<original_code>
#pragma GCC optimize ("O3")
#include <stdio.h>
#include <iostream>
#include <algorithm>
#include <cmath>
#include <numeric>
#include <vector>
#include <set>
#include <map>
#include <cstring>
#include <stack>
#include <unordered_map>
#define lld long long int
#define dbg1(vari1) cerr<<#vari1<<" = "<<(vari1)<<endl;
#define dbg2(vari1,vari2) cerr<<#vari1<<" = "<<(vari1)<<" "<<#vari2<<" = "<<(vari2)<<endl;
#define dbg3(vari1,vari2,vari3) cerr<<#vari1<<" = "<<(vari1)<<" "<<#vari2<<" = "<<(vari2)<<" "<<#vari3<<" = "<<(vari3)<<endl;
using namespace std;
lld gcd(lld a, lld b) 
{ 
    if (b == 0) 
        return a; 
    return gcd(b, a % b);  

} 
int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	int a,b,n;
	cin >> a >> b >> n;
	// if(n>=b)
	// {
	// 	cout << a/gcd(a,b) << "/" << b/gcd(a,b);
	// 	return 0;
	// }
	int x,y;
	long double dif=1.0/0.0;
	// dbg1(dif);
	for(lld j=1;j<=n;j++)
	{
		for(lld i=(j*a)/b-1;i<=((j*a)/b)+1;i++)
		{
			// dbg3(fabs((long double)i/j-(long double)a/b),i,j);
			if(fabs((long double)i/j-(long double)a/b)<dif)
			{
				dif=fabs(((long double)i/j)-((long double)a/b));
				// dbg2(x,y);
				x=i;
				y=j;
			}
		}
	}
	// dbg2(x,y);
	cout << x/gcd(x,y) << "/" << y/gcd(x,y);
}
